import {escapeHTML as safe} from '../../stream.js';

const copy={
 zh:{title:'七次主动来访，十四张候选',eyebrow:'三国 · 谋士',intro:'每项 A、B 两张，展示完整原图构图。先审人物、年龄、交付动作，再由 Claude 裁成 1200 × 480 接入剧情；这些图尚未采用。',choose:'选',full:'看完整构图',original:'查看原始 PNG',count:n=>`已选 ${n} / 7 项`,export:'整理我的选择',empty:'请先选择至少一项。',note:'选择只保存在当前浏览器。复制下面的文字发回聊天，即可说明你想采用哪几张。',pending:'未选择',close:'关闭完整构图',loading:'正在载入候选图…',failed:'候选图暂未载入，请刷新重试。',saved:'以下是你的选择；这不会自动采用或合并图片。'},
 en:{title:'Seven visits. Fourteen candidates.',eyebrow:'Three Kingdoms · The Strategist',intro:'Each scene has A and B candidates shown in full. Review identity, age and the handover before Claude crops approved images to 1200 × 480. These have not been adopted.',choose:'Choose',full:'View full composition',original:'View original PNG',count:n=>`${n} / 7 scenes selected`,export:'Show my choices',empty:'Choose at least one candidate first.',note:'Choices stay in this browser. Copy the text below into the chat to say which images you would like adopted.',pending:'Not chosen',close:'Close full composition',loading:'Loading candidates…',failed:'The candidates could not load. Refresh to try again.',saved:'Your choices below do not automatically adopt or merge any artwork.'}
};
const selectionKey='storydate.relations-art-review.115.v1';
let lang='zh',choices={},data,exported=false;
try{const saved=localStorage.getItem('sd.lang');lang=['zh','en'].includes(saved)?saved:navigator.language.startsWith('zh')?'zh':'en';choices=JSON.parse(localStorage.getItem(selectionKey)||'{}')||{};}catch{}
const root=document.querySelector('#review'),bar=document.querySelector('#selection-bar'),dialog=document.querySelector('#full-frame');
const validChoice=id=>['A','B'].includes(choices[id])?choices[id]:null;
function selectionText(){return data.groups.map(g=>`${g.id} · ${g.title[lang]}: ${validChoice(g.id)||copy[lang].pending}`).join('\n');}
function drawBar(){const l=copy[lang],count=data.groups.filter(g=>validChoice(g.id)).length;bar.innerHTML=`<div class="selection-inner"><p role="status">${l.count(count)}</p><button type="button" class="primary" data-export>${exported?(lang==='zh'?'收起选择':'Hide choices'):l.export}</button></div>${exported?`<div class="export"><textarea readonly aria-label="${safe(l.export)}">${safe(selectionText())}</textarea><p>${l.saved} ${l.note}</p></div>`:''}`;}
function draw(){const l=copy[lang];document.documentElement.lang=lang;document.title=(lang==='zh'?'关系场景候选':'Relationship scene candidates')+' · StoryDate';document.querySelector('.languages').setAttribute('aria-label',lang==='zh'?'语言':'Language');document.querySelectorAll('[data-language]').forEach(b=>b.setAttribute('aria-pressed',String(b.dataset.language===lang)));document.querySelector('#close-frame').setAttribute('aria-label',l.close);root.innerHTML=`<div class="intro"><p class="eyebrow">${l.eyebrow}</p><h1>${l.title}</h1><p>${l.intro}</p><a class="batch-link" href="../fates/index.html">${lang==='zh'?'另看：四类命运图（已有 A/B 候选）':'Also review: four fate outcomes (existing A/B candidates)'} ↗</a></div>${data.groups.map(g=>`<section aria-labelledby="${g.id}"><h2 id="${g.id}">${safe(g.title[lang])}</h2><div class="variants">${g.variants.map(v=>`<article class="candidate ${validChoice(g.id)===v.candidate?'selected':''}" data-id="${g.id}" data-candidate="${v.candidate}"><img class="banner" src="${v.image}" alt="${safe(g.title[lang]+' '+v.candidate)}" width="${v.dimensions[0]}" height="${v.dimensions[1]}" loading="lazy"><div class="candidate-body"><label><input type="radio" name="${g.id}" value="${v.candidate}" ${validChoice(g.id)===v.candidate?'checked':''}><strong>${l.choose} ${v.candidate}</strong></label><p>${safe(v.note[lang])}</p><button type="button" data-full="${g.id}" data-variant="${v.candidate}">${l.full} ↗</button><a href="${v.original}" target="_blank" rel="noopener">${l.original} ↗</a></div></article>`).join('')}</div></section>`).join('')}`;drawBar();}
root.addEventListener('change',e=>{const input=e.target.closest('input[type=radio]');if(!input||!data.groups.some(g=>g.id===input.name)||!['A','B'].includes(input.value))return;choices[input.name]=input.value;try{localStorage.setItem(selectionKey,JSON.stringify(choices));}catch{}root.querySelectorAll('.candidate').forEach(card=>card.classList.toggle('selected',validChoice(card.dataset.id)===card.dataset.candidate));drawBar();});
root.addEventListener('click',e=>{const b=e.target.closest('[data-full]');if(!b)return;const g=data.groups.find(g=>g.id===b.dataset.full),v=g?.variants.find(v=>v.candidate===b.dataset.variant);if(!v)return;dialog.querySelector('h2').textContent=g.title[lang]+' · '+v.candidate;const img=dialog.querySelector('img');img.src=v.full;img.alt=g.title[lang]+' '+v.candidate;const a=dialog.querySelector('a');a.href=v.original;a.textContent=copy[lang].original+' ↗';dialog.showModal();});
document.querySelector('#close-frame').onclick=()=>dialog.close();
bar.addEventListener('click',e=>{if(!e.target.closest('[data-export]'))return;if(exported){exported=false;drawBar();return;}if(!data.groups.some(g=>validChoice(g.id))){bar.querySelector('[role=status]').textContent=copy[lang].empty;return;}exported=true;drawBar();const field=bar.querySelector('textarea');field.focus();field.select();});
document.querySelectorAll('[data-language]').forEach(b=>b.onclick=()=>{lang=b.dataset.language;try{localStorage.setItem('sd.lang',lang);}catch{}if(dialog.open)dialog.close();if(data)draw();});
try{const response=await fetch('./manifest.json');if(!response.ok)throw Error('Manifest unavailable');data=await response.json();if(!Array.isArray(data.groups)||data.groups.length!==7)throw Error('Invalid manifest');draw();}catch{root.replaceChildren(Object.assign(document.createElement('p'),{textContent:copy[lang].failed}));}
